//! Parity port of the original roster filter rules and price-block decorator.
use crate::format::format_tag;
use crate::types::{BaseCodeCache, ItemQuality, Price, PricedItem, Roster};
use std::collections::{BTreeMap, BTreeSet};

pub const PRICE_BLOCK_START: &str = "// === PD2 PRICE TAGS (generated by pd2_lootfilter) START ===";
pub const PRICE_BLOCK_END: &str = "// === PD2 PRICE TAGS (generated by pd2_lootfilter) END ===";
pub const POTION_BLOCK_START: &str =
    "// === PD2 POTION DISPLAY (generated by pd2_lootfilter) START ===";
pub const POTION_BLOCK_END: &str =
    "// === PD2 POTION DISPLAY (generated by pd2_lootfilter) END ===";

/// Ring, amulet, and jewel bases each match many distinct items in-game.
pub const EXCLUDED_BASE_CODES: [&str; 3] = ["rin", "amu", "jew"];

fn excluded(base_code: &str) -> bool {
    EXCLUDED_BASE_CODES.contains(&base_code)
}

fn condition(item: &PricedItem) -> &str {
    match item {
        PricedItem::Unique { base_code, .. } => base_code,
        PricedItem::Set { base_code, .. } => base_code,
        PricedItem::Fixed { condition, .. } => condition,
    }
}

fn display_condition(item: &PricedItem) -> String {
    match item {
        PricedItem::Unique { .. } => format!("UNI ID {}", condition(item)),
        PricedItem::Set { .. } => format!("SET ID {}", condition(item)),
        PricedItem::Fixed { .. } => condition(item).to_owned(),
    }
}

pub fn resolve_priced_items(
    roster: &Roster,
    cache: &BaseCodeCache,
    prices: &BTreeMap<String, Price>,
) -> Vec<PricedItem> {
    let mut items = Vec::new();
    let mut seen_unique_id = BTreeSet::new();
    // BTreeMap iteration gives deterministic name order, unlike the original
    // insertion-ordered Map; dedup/price decisions are per name anyway.
    for (name, entry) in roster {
        let Some(price) = prices.get(name) else {
            continue;
        };
        match entry.kind {
            ItemQuality::Unique => {
                let Some(unique_id) = entry.unique_id else {
                    continue;
                };
                if seen_unique_id.contains(&unique_id) {
                    continue;
                }
                let Some(base_code) = cache.uniques.get(&unique_id.to_string()) else {
                    continue;
                };
                if excluded(base_code) {
                    continue;
                }
                seen_unique_id.insert(unique_id);
                items.push(PricedItem::Unique {
                    base_code: base_code.clone(),
                    price: price.clone(),
                });
            }
            ItemQuality::Set => {
                let Some(base_code) = cache.sets.get(name) else {
                    continue;
                };
                if excluded(base_code) {
                    continue;
                }
                items.push(PricedItem::Set {
                    base_code: base_code.clone(),
                    price: price.clone(),
                });
            }
        }
    }
    items
}

/// One rule per filter condition; conditions sorted for byte-stable output.
pub fn build_block(items: &[PricedItem]) -> String {
    let mut groups: BTreeMap<String, Vec<Price>> = BTreeMap::new();
    for item in items {
        let price = match item {
            PricedItem::Unique { price, .. }
            | PricedItem::Set { price, .. }
            | PricedItem::Fixed { price, .. } => price.clone(),
        };
        groups
            .entry(display_condition(item))
            .or_default()
            .push(price);
    }
    let mut lines = vec![PRICE_BLOCK_START.to_owned()];
    for (cond, prices) in groups {
        let tag = format_tag(&prices).expect("group is non-empty");
        lines.push(format!(
            "ItemDisplay[{cond}]: %NAME%%GOLD% | {tag}%CONTINUE%"
        ));
    }
    lines.push(PRICE_BLOCK_END.to_owned());
    lines.join("\n")
}

/// Remove the first delimited block, plus one blank line on each side.
/// Splitting on '\n' keeps any '\r' bytes on the surviving lines.
fn strip_block(filter_text: &str, start: &str, end: &str) -> String {
    let mut lines: Vec<&str> = filter_text.split('\n').collect();
    let Some(start_idx) = lines.iter().position(|line| line.trim() == start) else {
        return filter_text.to_owned();
    };
    let Some(offset) = lines[start_idx..]
        .iter()
        .position(|line| line.trim() == end)
    else {
        return filter_text.to_owned();
    };
    let end_idx = start_idx + offset;
    let mut from = start_idx;
    let mut to = end_idx;
    if from > 0 && lines[from - 1].trim().is_empty() {
        from -= 1;
    }
    if to + 1 < lines.len() && lines[to + 1].trim().is_empty() {
        to += 1;
    }
    lines.drain(from..=to);
    lines.join("\n")
}

/// Insert after the last top-level `ItemDisplayFilterName[]` declaration.
fn find_insertion_line(lines: &[&str]) -> usize {
    lines
        .iter()
        .rposition(|line| line.starts_with("ItemDisplayFilterName[]"))
        .map_or(0, |index| index + 1)
}

/// Inject the price block, stripping any prior price block and legacy potion
/// block. Potion display is intentionally not re-injected. Idempotent.
pub fn decorate(filter_text: &str, items: &[PricedItem]) -> String {
    let text = strip_block(filter_text, PRICE_BLOCK_START, PRICE_BLOCK_END);
    let text = strip_block(&text, POTION_BLOCK_START, POTION_BLOCK_END);
    let mut lines: Vec<String> = text.split('\n').map(str::to_owned).collect();
    let at = {
        let refs: Vec<&str> = lines.iter().map(String::as_str).collect();
        find_insertion_line(&refs)
    };
    lines.splice(at..at, [String::new(), build_block(items), String::new()]);
    lines.join("\n")
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::types::{ItemQuality, RosterEntry};

    fn price(median: f64, median_samples: u64) -> Price {
        Price {
            median,
            median_samples,
        }
    }
    fn entry(kind: ItemQuality, unique_id: Option<u64>) -> RosterEntry {
        RosterEntry { kind, unique_id }
    }
    fn unique(base_code: &str, median: f64) -> PricedItem {
        PricedItem::Unique {
            base_code: base_code.into(),
            price: price(median, 10),
        }
    }
    fn sample() -> &'static str {
        "// header\nItemDisplayFilterName[]: Base\nItemDisplayFilterName[]: Strict\nItemDisplay[box]: %NAME%{%NAME%}\nItemDisplay[UNI ID usk]: %NAME%{%NAME%}"
    }
    fn decorated() -> String {
        decorate(sample(), &[unique("usk", 0.1)])
    }

    #[test]
    fn uses_the_priced_alias_and_dedups_by_unique_id_after_the_price_check() {
        let roster = [
            ("Oculus".to_owned(), entry(ItemQuality::Unique, Some(5))),
            ("The Oculus".to_owned(), entry(ItemQuality::Unique, Some(5))),
        ]
        .into_iter()
        .collect();
        let cache = BaseCodeCache {
            uniques: [("5".into(), "oba".into())].into_iter().collect(),
            sets: Default::default(),
        };
        let prices = [("Oculus".to_owned(), price(2.0, 10))]
            .into_iter()
            .collect();
        assert_eq!(
            resolve_priced_items(&roster, &cache, &prices),
            vec![PricedItem::Unique {
                base_code: "oba".into(),
                price: price(2.0, 10)
            },]
        );
    }

    #[test]
    fn drops_ring_amulet_and_jewel_bases_for_uniques_and_sets() {
        let roster: Roster = [
            ("Angelic Halo".to_owned(), entry(ItemQuality::Set, None)),
            (
                "Mara's Kaleidoscope".to_owned(),
                entry(ItemQuality::Unique, Some(11)),
            ),
            (
                "Rainbow Facet".to_owned(),
                entry(ItemQuality::Unique, Some(12)),
            ),
            ("Shako".to_owned(), entry(ItemQuality::Unique, Some(13))),
            (
                "Stone of Jordan".to_owned(),
                entry(ItemQuality::Unique, Some(10)),
            ),
        ]
        .into_iter()
        .collect();
        let cache = BaseCodeCache {
            uniques: [
                ("10".into(), "rin".into()),
                ("11".into(), "amu".into()),
                ("12".into(), "jew".into()),
                ("13".into(), "ush".into()),
            ]
            .into_iter()
            .collect(),
            sets: [("Angelic Halo".into(), "rin".into())]
                .into_iter()
                .collect(),
        };
        let prices = roster
            .keys()
            .map(|name| (name.clone(), price(0.1, 10)))
            .collect();
        assert_eq!(
            resolve_priced_items(&roster, &cache, &prices),
            vec![PricedItem::Unique {
                base_code: "ush".into(),
                price: price(0.1, 10)
            },]
        );
    }

    #[test]
    fn resolves_deterministically_in_name_order_and_keeps_unpriced_names_out() {
        let roster = ["Zeta", "Alpha", "Beta"]
            .map(|n| (n.to_owned(), entry(ItemQuality::Set, None)))
            .into_iter()
            .collect();
        let cache = BaseCodeCache {
            uniques: Default::default(),
            sets: ["Alpha", "Beta", "Zeta"]
                .map(|n| (n.to_owned(), format!("x{n}")))
                .into_iter()
                .collect(),
        };
        let prices = [
            ("Zeta".to_owned(), price(1.0, 10)),
            ("Alpha".to_owned(), price(2.0, 10)),
        ]
        .into_iter()
        .collect();
        let items = resolve_priced_items(&roster, &cache, &prices);
        assert_eq!(
            items,
            vec![
                PricedItem::Set {
                    base_code: "xAlpha".into(),
                    price: price(2.0, 10)
                },
                PricedItem::Set {
                    base_code: "xZeta".into(),
                    price: price(1.0, 10)
                },
            ]
        );
    }

    #[test]
    fn repeated_empty_roster_and_prices_yield_no_items() {
        assert!(
            resolve_priced_items(&Roster::new(), &BaseCodeCache::default(), &BTreeMap::new())
                .is_empty()
        );
    }

    #[test]
    fn build_block_emits_one_rule_per_condition_for_unique_set_and_fixed() {
        let items = vec![
            unique("usk", 0.1),
            PricedItem::Set {
                base_code: "xtb".into(),
                price: price(5.0, 10),
            },
            PricedItem::Fixed {
                condition: "RUNE=30".into(),
                category: "rune".into(),
                price: price(3.0, 10),
            },
        ];
        let block = build_block(&items);
        assert!(block.starts_with(PRICE_BLOCK_START));
        assert!(block.ends_with(PRICE_BLOCK_END));
        assert!(
            block.contains("ItemDisplay[UNI ID usk]: %NAME%%GOLD% | 0.1 HR%CONTINUE%"),
            "{block}"
        );
        assert!(
            block.contains("ItemDisplay[SET ID xtb]: %NAME%%GOLD% | 5 HR%CONTINUE%"),
            "{block}"
        );
        assert!(
            block.contains("ItemDisplay[RUNE=30]: %NAME%%GOLD% | 3 HR%CONTINUE%"),
            "{block}"
        );
        assert_eq!(block.lines().count(), 5);
    }

    #[test]
    fn build_block_spans_shared_conditions_and_sorts_deterministically() {
        let items = vec![
            PricedItem::Fixed {
                condition: "RUNE=30".into(),
                category: "rune".into(),
                price: price(3.0, 10),
            },
            unique("uar", 120.0),
            unique("uar", 5.0),
            PricedItem::Set {
                base_code: "xtb".into(),
                price: price(0.1, 2),
            },
        ];
        let block = build_block(&items);
        let lines: Vec<_> = block.lines().collect();
        assert_eq!(
            lines[1],
            "ItemDisplay[RUNE=30]: %NAME%%GOLD% | 3 HR%CONTINUE%"
        );
        assert_eq!(
            lines[2],
            "ItemDisplay[SET ID xtb]: %NAME%%GOLD% | 0.1 HR?%CONTINUE%"
        );
        assert_eq!(
            lines[3],
            "ItemDisplay[UNI ID uar]: %NAME%%GOLD% | 5 - 120 HR%CONTINUE%"
        );
        assert_eq!(build_block(&items), block);
        assert_eq!(
            build_block(&[
                items[1].clone(),
                items[0].clone(),
                items[3].clone(),
                items[2].clone()
            ]),
            block
        );
    }

    #[test]
    fn build_block_keeps_fixed_conditions_verbatim_without_catalog_inference() {
        let items = vec![PricedItem::Fixed {
            condition: "pk1".into(),
            category: "uber".into(),
            price: price(0.5, 10),
        }];
        assert!(build_block(&items).contains("ItemDisplay[pk1]: %NAME%%GOLD% | 0.5 HR%CONTINUE%"));
    }

    #[test]
    fn build_block_with_no_items_is_just_the_markers() {
        assert_eq!(
            build_block(&[]),
            format!("{PRICE_BLOCK_START}\n{PRICE_BLOCK_END}")
        );
    }

    #[test]
    fn strip_block_leaves_text_without_a_block_unchanged() {
        assert_eq!(
            strip_block(sample(), PRICE_BLOCK_START, PRICE_BLOCK_END),
            sample()
        );
    }

    #[test]
    fn strip_block_removes_the_price_block_but_not_other_blocks() {
        let no_price = strip_block(&decorated(), PRICE_BLOCK_START, PRICE_BLOCK_END);
        assert!(!no_price.contains(PRICE_BLOCK_START));
        assert!(!no_price.contains(PRICE_BLOCK_END));
        assert!(no_price.contains("ItemDisplay[box]"));
        assert!(no_price.contains("ItemDisplay[UNI ID usk]"));
    }

    #[test]
    fn strip_block_removes_a_legacy_potion_block_only() {
        let legacy = format!(
            "before\n\n{POTION_BLOCK_START}\nItemDisplay[hp1]: %RED%+\n{POTION_BLOCK_END}\n\nafter"
        );
        assert_eq!(
            strip_block(&legacy, POTION_BLOCK_START, POTION_BLOCK_END),
            "before\nafter"
        );
    }

    #[test]
    fn strip_block_ignores_an_unterminated_block() {
        let text = format!("{PRICE_BLOCK_START}\nItemDisplay[box]: x");
        assert_eq!(strip_block(&text, PRICE_BLOCK_START, PRICE_BLOCK_END), text);
    }

    #[test]
    fn strip_block_removes_only_the_first_block() {
        let once = format!("{PRICE_BLOCK_START}\nA\n{PRICE_BLOCK_END}");
        let text = format!("{once}\nmid\n{once}");
        assert_eq!(
            strip_block(&text, PRICE_BLOCK_START, PRICE_BLOCK_END),
            format!("mid\n{once}")
        );
    }

    #[test]
    fn find_insertion_line_returns_the_line_after_the_last_declaration() {
        assert_eq!(
            find_insertion_line(&sample().lines().collect::<Vec<_>>()),
            3
        );
    }

    #[test]
    fn find_insertion_line_returns_zero_without_declarations() {
        assert_eq!(find_insertion_line(&["ItemDisplay[box]: x"]), 0);
        assert_eq!(find_insertion_line(&[]), 0);
    }

    #[test]
    fn decorate_injects_only_the_price_block_and_no_potion_display() {
        let out = decorate(sample(), &[unique("usk", 0.1)]);
        assert!(out.contains(PRICE_BLOCK_START));
        assert!(out.contains("ItemDisplay[UNI ID usk]: %NAME%%GOLD% | 0.1 HR%CONTINUE%"));
        assert!(!out.contains(POTION_BLOCK_START), "{out}");
        assert!(!out.contains("PD2 POTION DISPLAY"), "{out}");
        assert!(!out.contains("ItemDisplay[hp1"), "{out}");
        assert!(!out.contains("%RED%+"), "{out}");
    }

    #[test]
    fn decorate_strips_an_existing_legacy_potion_block_without_replacing_it() {
        let legacy = format!(
            "{}\n\n{POTION_BLOCK_START}\nItemDisplay[rvs]: %PURPLE%*\n{POTION_BLOCK_END}\n",
            sample()
        );
        let out = decorate(&legacy, &[unique("usk", 0.1)]);
        assert!(!out.contains(POTION_BLOCK_START), "{out}");
        assert!(!out.contains("ItemDisplay[rvs]"), "{out}");
        assert!(out.contains(PRICE_BLOCK_START));
    }

    #[test]
    fn decorate_inserts_after_declarations_and_before_item_rules() {
        let out = decorate(sample(), &[unique("usk", 0.1)]);
        let lines: Vec<_> = out.lines().collect();
        let price_line = lines.iter().position(|l| *l == PRICE_BLOCK_START).unwrap();
        let box_line = lines
            .iter()
            .position(|l| l.starts_with("ItemDisplay[box]"))
            .unwrap();
        assert_eq!(price_line, 4);
        assert!(price_line < box_line);
        assert_eq!(lines[price_line - 1], "");
        assert_eq!(
            lines[price_line + 1],
            "ItemDisplay[UNI ID usk]: %NAME%%GOLD% | 0.1 HR%CONTINUE%"
        );
    }

    #[test]
    fn decorate_is_idempotent_with_one_block_and_stable_bytes() {
        let once = decorated();
        let twice = decorate(&once, &[unique("usk", 0.1)]);
        assert_eq!(twice, once);
        assert_eq!(once.matches("PD2 PRICE TAGS").count(), 2);
        assert_eq!(decorate(&once, &[]), decorate(sample(), &[]));
    }

    #[test]
    fn decorate_keeps_author_text_and_preserves_crlf_lines() {
        let source = "// author\r\nItemDisplayFilterName[]: Base\r\nItemDisplay[box]: x\r\n";
        let out = decorate(source, &[unique("usk", 0.1)]);
        let lines: Vec<_> = out.lines().collect();
        assert_eq!(lines[0], "// author");
        assert_eq!(lines[1], "ItemDisplayFilterName[]: Base");
        assert_eq!(lines[2], "");
        assert_eq!(lines[3], PRICE_BLOCK_START);
        assert_eq!(lines[5], PRICE_BLOCK_END);
        assert_eq!(lines[7], "ItemDisplay[box]: x");
        assert!(out.contains("\r\n"), "{out:?}");
    }

    #[test]
    fn decorate_on_empty_input_adds_the_block_at_the_top() {
        let out = decorate("", &[unique("usk", 0.1)]);
        let lines: Vec<_> = out.lines().collect();
        assert_eq!(lines[0], "");
        assert_eq!(lines[1], PRICE_BLOCK_START);
        assert_eq!(lines[3], PRICE_BLOCK_END);
    }

    #[test]
    fn matches_original_typescript_output_on_a_differential_fixture() {
        // Reference produced by running src/decorate.ts under tsx, with its
        // potion block stripped to reflect the approved removal.
        let items = vec![
            unique("uar", 120.0),
            PricedItem::Fixed {
                condition: "RUNE=30".into(),
                category: "rune".into(),
                price: price(3.0, 10),
            },
            unique("uar", 5.0),
            PricedItem::Set {
                base_code: "xtb".into(),
                price: price(0.1, 2),
            },
            PricedItem::Fixed {
                condition: "pk1".into(),
                category: "uber".into(),
                price: price(0.333, 10),
            },
            unique("usk", 0.1),
        ];
        let source = [
            "// header",
            "",
            "ItemDisplayFilterName[]: Base",
            "ItemDisplayFilterName[]: Strict",
            "",
            "ItemDisplay[box]: %NAME%{%NAME%}",
            "ItemDisplay[UNI ID usk]: %NAME%{%NAME%}",
            "",
        ]
        .join("\n");
        let expected_block = "// === PD2 PRICE TAGS (generated by pd2_lootfilter) START ===\n\
ItemDisplay[RUNE=30]: %NAME%%GOLD% | 3 HR%CONTINUE%\n\
ItemDisplay[SET ID xtb]: %NAME%%GOLD% | 0.1 HR?%CONTINUE%\n\
ItemDisplay[UNI ID uar]: %NAME%%GOLD% | 5 - 120 HR%CONTINUE%\n\
ItemDisplay[UNI ID usk]: %NAME%%GOLD% | 0.1 HR%CONTINUE%\n\
ItemDisplay[pk1]: %NAME%%GOLD% | 0.33 HR%CONTINUE%\n\
// === PD2 PRICE TAGS (generated by pd2_lootfilter) END ===";
        assert_eq!(build_block(&items), expected_block);
        // A clean source that already has a blank line after the declarations
        // keeps it, so two blank lines separate the block from the first rule.
        let expected = format!(
            "// header\n\nItemDisplayFilterName[]: Base\nItemDisplayFilterName[]: Strict\n\n{expected_block}\n\n\nItemDisplay[box]: %NAME%{{%NAME%}}\nItemDisplay[UNI ID usk]: %NAME%{{%NAME%}}\n"
        );
        assert_eq!(decorate(&source, &items), expected);
        // Output produced by the original TypeScript decorator (price + potion
        // blocks) loses the potion block and the blank it owned, leaving the
        // historic single separator.
        let legacy = format!(
            "// header\nItemDisplayFilterName[]: Base\nItemDisplayFilterName[]: Strict\n\n{expected_block}\n\n{POTION_BLOCK_START}\nItemDisplay[hp1]: %RED%+\n{POTION_BLOCK_END}\n\nItemDisplay[box]: %NAME%{{%NAME%}}\n"
        );
        let redecorated = decorate(&legacy, &items);
        assert_eq!(
            redecorated,
            format!(
                "// header\nItemDisplayFilterName[]: Base\nItemDisplayFilterName[]: Strict\n\n{expected_block}\n\nItemDisplay[box]: %NAME%{{%NAME%}}\n"
            )
        );
    }

    #[test]
    fn resolves_uniques_by_id_and_sets_by_name_skipping_unpriced_and_codeless() {
        let roster = [
            (
                "Andariel's Visage".to_owned(),
                entry(ItemQuality::Unique, Some(346)),
            ),
            ("Aldur's Advance".to_owned(), entry(ItemQuality::Set, None)),
            ("No Price".to_owned(), entry(ItemQuality::Unique, Some(77))),
            ("No Base".to_owned(), entry(ItemQuality::Unique, Some(88))),
        ]
        .into_iter()
        .collect();
        let cache = BaseCodeCache {
            uniques: [("346".into(), "usk".into()), ("77".into(), "xyz".into())]
                .into_iter()
                .collect(),
            sets: [("Aldur's Advance".into(), "xtb".into())]
                .into_iter()
                .collect(),
        };
        let prices = [
            ("Andariel's Visage", price(0.1, 10)),
            ("Aldur's Advance", price(0.1, 10)),
            ("No Base", price(0.1, 10)),
        ]
        .into_iter()
        .map(|(n, p)| (n.to_owned(), p))
        .collect();
        let items = resolve_priced_items(&roster, &cache, &prices);
        assert_eq!(items.len(), 2, "{items:?}");
        assert!(items.contains(&PricedItem::Unique {
            base_code: "usk".into(),
            price: price(0.1, 10)
        }));
        assert!(items.contains(&PricedItem::Set {
            base_code: "xtb".into(),
            price: price(0.1, 10)
        }));
    }
}
